"""Create an editable HyperFrames project with audio-aligned narrative subcompositions."""
import json,uuid,shutil,html,datetime
from pathlib import Path
from david_art import art
root=Path(__file__).resolve().parent.parent
work=root/'.mindstudio/david-work';data=json.loads((work/'aligned.json').read_text()); duration=339.441
key='free-'+str(uuid.uuid4());p=root/'.mindstudio/studio'/key;p.mkdir(parents=True);(p/'compositions').mkdir()
shutil.copy('/Users/user/Downloads/ma_narration_bf819bcd41.wav',p/'narration.wav');shutil.copy(root/'node_modules/gsap/dist/gsap.min.js',p/'gsap.min.js');shutil.copy(work/'transcription.txt',p/'transcription.txt');shutil.copy(work/'paroles.srt',p/'paroles.srt')
meta=dict(id=key,name='David · Le Goliath intérieur',createdAt=datetime.datetime.now(datetime.timezone.utc).isoformat());(p/'mindstudio-project.json').write_text(json.dumps(meta))
# Each index points to an actual paragraph in the supplied narration, aligned to speech.
beats=[(0,'lion','LE LION'),(1,'bear','L’OURS'),(2,'giant','GOLIATH'),(3,'spear','SAÜL'),(4,'crown','LA CHUTE'),(5,'mirror','COMMENT ?'),(7,'shadow','EN LUI'),(8,'roof','AVANT BATH-SHÉBA'),(10,'king','LE ROI'),(13,'army','LE TEMPS DE LA GUERRE'),(15,'palace','JÉRUSALEM'),(16,'battle','AU FRONT'),(17,'throne','AU PALAIS'),(20,'roof','UN SOIR'),(21,'bath','LE REGARD'),(23,'choice','S’ARRÊTER'),(25,'palace','QUI EST-ELLE ?'),(27,'loyalty','LA FEMME D’URIE'),(29,'choice','ENCORE UN CHOIX'),(31,'doors','LA PORTE SE REFERME'),(33,'message','UN MESSAGE'),(35,'sealed','LE SECRET'),(36,'choice','VÉRITÉ OU CONTRÔLE'),(39,'shadow','CACHER'),(40,'army','LE RETOUR D’URIE'),(42,'doors','LE PLAN'),(43,'loyalty','LE REFUS'),(44,'battle','SES COMPAGNONS'),(46,'loyalty','FIDÉLITÉ / TRAHISON'),(49,'doors','UN NOUVEL ÉCHEC'),(51,'choice','AVOUER ?'),(53,'letter','L’ORDRE'),(54,'sealed','URIE DOIT MOURIR'),(56,'delivery','LE MESSAGER'),(57,'letter','SA PROPRE CONDAMNATION'),(58,'battle','LE FRONT'),(59,'death','URIE'),(60,'stairs','LA PROGRESSION'),(65,'stairs','LE SECRET GRANDIT'),(69,'stairs','MARCHE APRÈS MARCHE'),(71,'mirror','ET NOUS ?'),(73,'sealed','LE PREMIER MENSONGE'),(75,'giant','UN ENNEMI VISIBLE'),(77,'desire','LE DÉSIR'),(80,'wedding','EN APPARENCE'),(81,'shadow','RIEN N’EST CACHÉ'),(83,'nathan','NATHAN'),(86,'flock','L’HOMME RICHE'),(87,'lamb','UNE SEULE BREBIS'),(88,'taken','L’INJUSTICE'),(89,'king','LE JUGEMENT'),(91,'nathan','LE REGARD DE NATHAN'),(93,'accuse','TU ES CET HOMME-LÀ'),(95,'mirror','SON PROPRE JUGEMENT'),(97,'prayer','NE PLUS CACHER'),(100,'prayer','J’AI PÉCHÉ'),(102,'heart','UN CŒUR PUR'),(104,'choice','MA SITUATION ?'),(107,'heart','CHANGE-MOI'),(108,'giant','NI GOLIATH'),(109,'spear','NI SAÜL'),(110,'army','NI UNE ARMÉE'),(111,'shadow','EN LUI'),(112,'mirror','ET TOI ?'),(114,'doors','LES COMBATS VISIBLES'),(118,'mirror','CE QUI RESTE EN TOI'),(119,'crown','L’ORGUEIL'),(120,'sealed','LA COLÈRE'),(121,'king','LA VALIDATION'),(122,'desire','LE DÉSIR'),(123,'shadow','LA JALOUSIE'),(124,'stairs','SOUS CONTRÔLE ?'),(125,'prayer','SEUL AVEC SOI'),(126,'doors','ENLÈVE MES ENNEMIS'),(128,'heart','MONTRE-MOI'),(130,'giant','DEVANT TOI'),(131,'shadow','CACHÉ EN TOI'),(133,'prayer','LA PLUS GRANDE VICTOIRE')]
starts=[];t=0
for s in data['scenes']:starts.append(t);t+=s['duration']
css='''*{box-sizing:border-box}html,body{margin:0;background:#101b26}.frame{position:relative;width:1280px;height:720px;overflow:hidden;color:#efdfbf;font-family:Georgia,serif}.picture{position:absolute;inset:0;width:1280px;height:720px}.vignette{position:absolute;inset:0;background:linear-gradient(0deg,#08121bea,transparent 32%,transparent 80%,#08121b88)}.eyebrow{position:absolute;left:68px;top:52px;font:11px Arial;letter-spacing:3px;color:#c9ad7b}.title{position:absolute;left:68px;top:88px;max-width:1120px;font:44px/1.15 Georgia,serif;letter-spacing:1px}.rule{position:absolute;left:68px;top:155px;width:66px;height:2px;background:#c9ad7b}.lyrics{position:absolute;left:140px;right:140px;bottom:35px;text-align:center;font:26px/1.4 Arial;color:#fff6e5;z-index:10;text-shadow:0 2px 9px #000}.word{display:inline}.wash{position:absolute;inset:0;background:#0d1925;pointer-events:none}'''
mounts=[];board=[]
for i,(idx,kind,label) in enumerate(beats):
 a=starts[idx];b=starts[beats[i+1][0]] if i+1<len(beats) else duration;d=b-a;cid=f'scene-{i+1:02}'; title=html.escape(label)
 # Detail insert gives a changed viewpoint rather than repeating an identical card.
 zoom=1.12 if kind in ['letter','sealed','heart','crown','death'] else 1
 picture=f'<svg class="picture" id="picture-{i}" viewBox="0 0 1280 720"><defs><radialGradient id="sky"><stop stop-color="#30444e"/><stop offset="1" stop-color="#101b26"/></radialGradient></defs><g id="world-{i}">{art(kind)}</g></svg>'
 script=f"const tl=gsap.timeline({{paused:true}});tl.fromTo('#picture-{i}',{{scale:{zoom},x:0}},{{scale:{zoom+0.035},x:{-10 if i%2 else 10},duration:{d},ease:'none',transformOrigin:'50% 52%'}},0);tl.fromTo('#label-{i}',{{opacity:0,y:12}},{{opacity:1,y:0,duration:.42}},.12);"
 if kind=='stairs':
  for j in range(7):script+=f"tl.fromTo('#world-{i} #step-{j}',{{opacity:.18}},{{opacity:1,duration:.2}},{min(j*.5,max(0,d-.3))});"
 if kind=='delivery':script+=f"tl.fromTo('#world-{i}',{{x:-22}},{{x:0,duration:{min(2,d)},ease:'power2.out'}},0);"
 script+=f"window.__timelines=window.__timelines||{{}};window.__timelines['{cid}']=tl;"
 (p/'compositions'/f'{cid}.html').write_text(f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><script src="gsap.min.js"></script><style>{css.replace(".frame{", "#"+cid+"{")}</style></head><body><main class="frame" id="{cid}" data-composition-id="{cid}" data-start="0" data-duration="{d}" data-width="1280" data-height="720">{picture}<div class="vignette"></div><div class="eyebrow">DAVID · LE GOLIATH INTÉRIEUR</div><div id="label-{i}" class="title">{title}</div><div class="rule"></div></main><script>{script}</script></body></html>')
 mounts.append(f'<div id="clip-{i}" class="clip" data-composition-id="{cid}" data-composition-src="compositions/{cid}.html" data-start="{a}" data-duration="{d}" data-track-index="0" style="position:absolute;inset:0"></div>')
 board.append(dict(id=cid,start=a,end=b,title=label,visual=kind,paragraph=idx))
caps=[]
for i,c in enumerate(data['cues']):
 text='<br>'.join(' '.join(html.escape(w['text']) for w in line) for line in c['lines'])
 caps.append(f'<div id="caption-{i}" class="clip lyrics" data-start="{c["start"]}" data-duration="{c["end"]-c["start"]}" data-track-index="2">{text}</div>')
(p/'index.html').write_text(f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>{css}</style></head><body><main class="frame" id="main" data-composition-id="main" data-no-timeline data-start="0" data-duration="{duration}" data-width="1280" data-height="720" data-fps="24">'+''.join(mounts)+''.join(caps)+f'<audio id="narration" class="clip" src="narration.wav" data-start="0" data-duration="{duration}" data-track-index="1" data-volume="1"></audio></main></body></html>')
(p/'storyboard.json').write_text(json.dumps(board,ensure_ascii=False,indent=2));(p/'alignment.json').write_text(json.dumps(data,ensure_ascii=False));(work/'project.json').write_text(json.dumps(meta))
print(json.dumps(dict(**meta,shots=len(beats),captions=len(caps),exactRatio=data['exactRatio'])))
